package server

// router_org_claim_test.go — F31 fan-out (Finding C): files-bff's
// authenticated route group now mounts auth.RequireOrgClaim() immediately
// after auth.HTTPMiddleware, mirroring admin-bff's router.go mount. These
// tests drive a REAL signed JWT through the REAL New() wiring so a
// regression that dropped the mount would show up as an actual 200 instead
// of the 403 asserted below.

import (
	"context"
	"crypto/rand"
	"crypto/rsa"
	"encoding/base64"
	"encoding/json"
	"math/big"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	jose "github.com/go-jose/go-jose/v4"
	josejwt "github.com/go-jose/go-jose/v4/jwt"
	"github.com/stretchr/testify/require"
	"google.golang.org/grpc"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	corpusv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/files/corpus/v1"
	"github.com/zenithflowinc/omnicore-platform/services/files-bff/internal/filesclient"
)

type orgClaimOIDCStub struct {
	srv    *httptest.Server
	key    *rsa.PrivateKey
	kid    string
	Issuer string
}

func newOrgClaimOIDCStub(t *testing.T) *orgClaimOIDCStub {
	t.Helper()
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	require.NoError(t, err)
	stub := &orgClaimOIDCStub{key: key, kid: "org-claim-test-key-1"}

	mux := http.NewServeMux()
	mux.HandleFunc("/.well-known/openid-configuration", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"issuer":                                stub.Issuer,
			"authorization_endpoint":                stub.Issuer + "/authorize",
			"token_endpoint":                        stub.Issuer + "/token",
			"jwks_uri":                              stub.Issuer + "/keys",
			"id_token_signing_alg_values_supported": []string{"RS256"},
			"response_types_supported":              []string{"code"},
			"subject_types_supported":               []string{"public"},
		})
	})
	mux.HandleFunc("/keys", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		n := base64.RawURLEncoding.EncodeToString(key.PublicKey.N.Bytes())
		e := base64.RawURLEncoding.EncodeToString(big.NewInt(int64(key.PublicKey.E)).Bytes())
		_ = json.NewEncoder(w).Encode(map[string]any{
			"keys": []map[string]any{{
				"kty": "RSA", "alg": "RS256", "use": "sig", "kid": stub.kid, "n": n, "e": e,
			}},
		})
	})

	stub.srv = httptest.NewServer(mux)
	stub.Issuer = stub.srv.URL
	t.Cleanup(stub.srv.Close)
	return stub
}

func (s *orgClaimOIDCStub) mintToken(t *testing.T, audience, orgID string) string {
	t.Helper()
	sig, err := jose.NewSigner(
		jose.SigningKey{Algorithm: jose.RS256, Key: s.key},
		(&jose.SignerOptions{}).WithType("JWT").WithHeader("kid", s.kid),
	)
	require.NoError(t, err)

	now := time.Now()
	std := josejwt.Claims{
		Issuer:   s.Issuer,
		Subject:  "org-claim-test-caller",
		Audience: josejwt.Audience{audience},
		IssuedAt: josejwt.NewNumericDate(now),
		Expiry:   josejwt.NewNumericDate(now.Add(5 * time.Minute)),
	}
	extra := struct {
		OrgID string `json:"org_id,omitempty"`
	}{OrgID: orgID}

	signed, err := josejwt.Signed(sig).Claims(std).Claims(extra).Serialize()
	require.NoError(t, err)
	return signed
}

func newOrgClaimVerifier(t *testing.T, stub *orgClaimOIDCStub, audience string) *auth.JWTVerifier {
	t.Helper()
	v, err := auth.NewJWTVerifier(context.Background(), stub.Issuer, "", audience)
	require.NoError(t, err)
	return v
}

const orgClaimTestAudience = "files-bff"

// fakeOrgClaimCorpusClient satisfies corpusv1.CorpusServiceClient (by
// embedding it as nil and overriding only List) so
// TestRouter_RequireOrgClaim_AllowsPopulatedOrgClaim can drive a request all
// the way through the corpora route without a live gRPC channel and without
// panicking on a nil client.
type fakeOrgClaimCorpusClient struct {
	corpusv1.CorpusServiceClient
}

func (fakeOrgClaimCorpusClient) List(_ context.Context, _ *corpusv1.ListRequest, _ ...grpc.CallOption) (*corpusv1.ListResponse, error) {
	return &corpusv1.ListResponse{}, nil
}

// TestRouter_RequireOrgClaim_RejectsEmptyOrgClaim proves the authenticated
// group's mount: a validly-signed JWT with an empty org_id claim must be
// 403'd by RequireOrgClaim before the corpora route ever runs.
func TestRouter_RequireOrgClaim_RejectsEmptyOrgClaim(t *testing.T) {
	stub := newOrgClaimOIDCStub(t)
	verifier := newOrgClaimVerifier(t, stub, orgClaimTestAudience)
	token := stub.mintToken(t, orgClaimTestAudience, "")

	h := New(Deps{
		Verifier:    verifier,
		FilesClient: &filesclient.Client{Corpus: fakeOrgClaimCorpusClient{}},
	})
	req := httptest.NewRequest(http.MethodGet, "/api/v1/files/corpora", nil)
	req.Header.Set("Authorization", "Bearer "+token)
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)

	require.Equal(t, http.StatusForbidden, rec.Code,
		"an empty org_id claim must be rejected by the router's RequireOrgClaim mount; body: %s", rec.Body.String())
}

// TestRouter_RequireOrgClaim_AllowsPopulatedOrgClaim is the positive
// control: a populated org_id claim must reach the corpora handler (200 from
// the fake client), proving the mount doesn't block legitimate traffic.
func TestRouter_RequireOrgClaim_AllowsPopulatedOrgClaim(t *testing.T) {
	stub := newOrgClaimOIDCStub(t)
	verifier := newOrgClaimVerifier(t, stub, orgClaimTestAudience)
	token := stub.mintToken(t, orgClaimTestAudience, "org-a")

	h := New(Deps{
		Verifier:    verifier,
		FilesClient: &filesclient.Client{Corpus: fakeOrgClaimCorpusClient{}},
	})
	req := httptest.NewRequest(http.MethodGet, "/api/v1/files/corpora", nil)
	req.Header.Set("Authorization", "Bearer "+token)
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)

	require.Equal(t, http.StatusOK, rec.Code,
		"a populated org_id claim must reach the handler, not be blocked; body: %s", rec.Body.String())
}

// TestRouter_HealthzIsPublic_NoTokenRequired pins that the F31 fan-out did
// not accidentally widen the auth boundary onto the public health probe.
func TestRouter_HealthzIsPublic_NoTokenRequired(t *testing.T) {
	h := New(Deps{FilesClient: &filesclient.Client{}})
	req := httptest.NewRequest(http.MethodGet, "/healthz", nil)
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)

	require.Equal(t, http.StatusOK, rec.Code, "body: %s", rec.Body.String())
}


