// Package server holds the HTTP router for files-bff.
//
// Sub-PR 3 wires only /healthz. Sub-PR 4 adds all /api/v1/* business routes
// that pass through to files-svc.
package server

import (
	"log/slog"
	"net/http"
	"net/netip"
	"os"
	"time"

	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
	"github.com/go-chi/httprate"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/featureflags"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/httpserver"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/idempotency"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/security"
	"github.com/zenithflowinc/omnicore-platform/services/files-bff/internal/filesclient"
	"github.com/zenithflowinc/omnicore-platform/services/files-bff/internal/handlers"
)

// Rate-limit budget per (org_id, IP) bucket. Matches the admin-bff default
// budget (600 req/min) from platform/scripts/coverage-gate.sh T1.7.
const (
	defaultRateLimit = 600
	rateLimitWindow  = time.Minute
)

// routeTimeout is the per-request budget applied to ordinary CRUD/read
// routes via httpserver.Timeout, matching grpcclient.TierDefault as the
// platform's general RPC ceiling. NOT applied to GetRawFile or the corpora
// document Upload route — see their registration below.
const routeTimeout = 30 * time.Second

// Deps groups the runtime dependencies the router needs.
type Deps struct {
	// MetricsHandler serves the Prometheus /metrics scrape endpoint (PUBLIC).
	// MetricsMiddleware wraps the entire router to record every request.
	// Both are set by main.go via observability after SetupMeter.
	MetricsHandler    http.Handler
	MetricsMiddleware func(http.Handler) http.Handler

	Verifier    *auth.JWTVerifier
	FilesClient *filesclient.Client
	// IdentityClient is optional; when nil the audit handlers fall back
	// to emitting raw user UUIDs in the actor field.
	IdentityClient handlers.IdentityFetcher
	// OrgClient resolves the caller's org-membership role from org-svc for the
	// trash-override routes (Purge/EmptyTrash/ListTrash). OPTIONAL — when nil,
	// the ResolveOrgRole middleware is a no-op pass-through and files-svc fails
	// the admin override closed (no x-org-role): the caller can still
	// purge/empty their own trash, but cannot reach another user's. Mounted
	// ONLY on the three override routes to avoid an org-svc round-trip on the
	// high-frequency corpora/documents/entity routes.
	OrgClient handlers.OrgRoleVerifier

	// FeatureFlagCache is an optional TTL-backed feature-flag cache. When
	// non-nil, RequireVerticalEnabled("files") is mounted on the authenticated
	// route group and returns 403 vertical_disabled when org-svc reports the
	// files vertical is disabled. A nil cache is a pass-through no-op
	// (fail-safe-open for local dev when ORG_SVC_ADDR is not configured).
	FeatureFlagCache *featureflags.Cache

	Logger      *slog.Logger
	S3          handlers.S3PutObjectAPI
	FilesBucket string

	// TrustedProxyCIDRs is the set of CIDR ranges trusted to supply a
	// truthful X-Forwarded-For / True-Client-IP chain, consumed by
	// security.ClientIPMiddleware. A request whose immediate peer
	// (RemoteAddr) falls outside this set has its client IP resolved from
	// RemoteAddr alone — any forged forwarding header is ignored.
	TrustedProxyCIDRs []netip.Prefix

	// IdemStore closes the Task 6.4 false-safety gap: files-mfe's shared API
	// client (frontends/files-mfe/src/api/client.ts) already sends a fresh
	// Idempotency-Key on every non-GET request, but until now files-bff
	// silently ignored it. Mounted once on the whole authenticated route
	// group below (rather than per-route) because the client sends the
	// header on every mutating call, not a specific subset — mounting per
	// group is equivalent and far less error-prone than enumerating every
	// POST/PUT/PATCH/DELETE route by hand. A nil store (the default) makes
	// idemMiddleware a pass-through no-op.
	IdemStore idempotency.Store
}

// idemMiddleware wraps store with idempotency.Middleware, or is a
// pass-through no-op when store is nil. See Deps.IdemStore.
func idemMiddleware(store idempotency.Store) func(http.Handler) http.Handler {
	if store == nil {
		return func(next http.Handler) http.Handler { return next }
	}
	return idempotency.Middleware(store)
}

// New returns a chi router wired with middleware + /healthz + /api/v1/* routes.
func New(deps Deps) http.Handler {
	logger := deps.Logger
	if logger == nil {
		logger = slog.Default()
	}

	r := chi.NewRouter()
	r.Use(middleware.RequestID)
	r.Use(security.ClientIPMiddleware(deps.TrustedProxyCIDRs))
	r.Use(middleware.Recoverer)
	r.Use(security.Middleware)

	// HTTP metrics middleware — wraps every route so the generic counters
	// are recorded for all traffic. Skipped when nil (tests without meter).
	if deps.MetricsMiddleware != nil {
		r.Use(deps.MetricsMiddleware)
	}

	r.Get("/healthz", healthzHandler)

	// PUBLIC Prometheus scrape endpoint — outside every auth/rate-limit group.
	if deps.MetricsHandler != nil {
		r.Handle("/metrics", deps.MetricsHandler)
	}

	corpusH := handlers.NewCorpusHandler(deps.FilesClient.Corpus, logger)
	entityH := handlers.NewEntityHandler(deps.FilesClient.Entity, logger)
	entityH.Identity = deps.IdentityClient
	edgeH := handlers.NewEdgeHandler(deps.FilesClient.Edge, logger)
	edgeH.Identity = deps.IdentityClient
	typesH := handlers.NewTypesHandler(
		deps.FilesClient.EntityType,
		deps.FilesClient.RelationshipType,
		logger,
	)
	documentH := handlers.NewDocumentHandler(deps.FilesClient.Document, deps.FilesClient.Corpus, deps.S3, deps.FilesBucket, logger)
	// #2755: ImportFromURL's SSRF guard is fail-closed by default. A local
	// dev stack serves images from private addresses, so it opts in here;
	// loopback and link-local stay denied regardless, so this can never
	// reach the cloud-metadata endpoint.
	documentH.AllowPrivateEgress = os.Getenv("FILES_BFF_ALLOW_PRIVATE_EGRESS") == "true"
	folderH := handlers.NewFolderHandler(deps.FilesClient.Folder, logger)
	ingestH := handlers.NewIngestHandler(deps.FilesClient.Ingest, logger)

	r.Group(func(r chi.Router) {
		r.Use(auth.HTTPMiddleware(deps.Verifier, auth.AuthRequired))
		// F31 fan-out: reject an empty org_id claim (unless migration:write
		// exempt) before any handler in this route group runs. Mirrors
		// admin-bff's router.go mount — see platform/libs/go/auth/roles.go.
		r.Use(auth.RequireOrgClaim())
		r.Use(auth.RejectAdminRoles())
		// Platform feature-flag gate (Security Invariant #8 is admin-plane
		// confinement; this is the capability gate): 403 vertical_disabled
		// when the "files" vertical is turned off platform-wide. Nil cache
		// (ORG_SVC_ADDR unset) is a pass-through no-op — fail-safe-open.
		if deps.FeatureFlagCache != nil {
			r.Use(featureflags.RequireVerticalEnabled(deps.FeatureFlagCache, "files"))
		}
		r.Use(httprate.Limit(defaultRateLimit, rateLimitWindow,
			httprate.WithKeyFuncs(security.KeyByOrgIDAndIP)))
		// Task 6.4 — honor the Idempotency-Key files-mfe already sends
		// rather than silently ignoring it. No-op when the header is absent.
		r.Use(idemMiddleware(deps.IdemStore))

		r.Route("/api/v1/files", func(r chi.Router) {
			// EXEMPT from httpserver.Timeout — registered directly on this
			// untimed router, not inside the Timeout-wrapped r.Group below.
			//
			// Upload (POST /corpora/{id}/documents) streams the multipart
			// body through to MinIO + files-svc; GetRawFile (GET
			// /documents/{id}/raw) streams the response body back via
			// http.Flusher (see document.go). A Timeout-armed request
			// context would cancel mid-stream and truncate either body —
			// see services/range-bff/internal/server/server.go's SSE route
			// for the same long-lived-stream-stays-outside-Timeout pattern.
			r.Post("/corpora/{id}/documents", documentH.Upload)
			// Registered alongside Upload (outside the JSON-body middleware
			// group below) because it shares Upload's pipeline and its
			// larger body/timeout envelope — it fetches the bytes itself
			// rather than reading a multipart part (#2755).
			r.Post("/corpora/{id}/documents:import", documentH.ImportFromURL)
			r.Get("/documents/{id}/raw", documentH.GetRawFile)

			r.Group(func(r chi.Router) {
				r.Use(httpserver.Timeout(routeTimeout))

				// Workspace shortcut — must be before /corpora to avoid route conflict.
				r.Get("/workspace/corpora", corpusH.Workspace)

				r.Route("/corpora", func(r chi.Router) {
					r.Post("/", corpusH.Create)
					r.Get("/", corpusH.List)
					r.Get("/{id}", corpusH.Get)
					r.Patch("/{id}", corpusH.Update)
					r.Delete("/{id}", corpusH.Delete)
					r.Get("/{id}/subgraph", corpusH.ListSubgraph)
					// NOTE: POST "/{id}/documents" (Upload) is registered above,
					// outside this Timeout-wrapped group.
					r.Get("/{id}/documents", documentH.List)
					// Folder routes scoped to a corpus.
					r.Route("/{corpusId}/folders", func(r chi.Router) {
						r.Post("/", folderH.Create)
						r.Get("/tree", folderH.GetTree)
						r.Get("/{folderId}/contents", folderH.ListContents)
						r.Get("/root/contents", folderH.ListContents)
					})

					// Trash + purge action verbs (ADR-008 + Trash spec §5).
					// Registered here at the /corpora scope (not nested inside
					// r.Route("/{id}", ...)) to avoid the chi v5 panic on
					// colon-suffix routes inside parameterised Route blocks.
					//
					// Trash/Restore/PreviewPurge do NOT use the org admin override —
					// they act only on the caller's own documents — so they stay
					// ungated (no org-svc round-trip).
					r.Post("/{id}/documents/{docId}:trash", documentH.Trash)
					r.Post("/{id}/documents/{docId}:restore", documentH.Restore)
					r.Post("/{id}/documents/{docId}:preview-purge", documentH.PreviewPurge)

					// Trash-override routes — Purge, ListTrash, EmptyTrash. files-svc
					// gates the admin override (act on ANY user's trashed docs, not
					// just the caller's own) on the caller's ORG-membership role
					// (OWNER/ADMIN), forwarded as x-org-role. ResolveOrgRole resolves
					// that role from org-svc and is mounted ONLY on these three;
					// every other files route is ungated. When OrgClient is nil the
					// middleware is a no-op pass-through and the override fails closed
					// downstream (the caller can still purge/empty their own trash).
					// Mirrors dialogue-bff's curation-route pattern.
					r.Group(func(r chi.Router) {
						r.Use(handlers.ResolveOrgRole(deps.OrgClient))
						r.Post("/{id}/documents/{docId}:purge", documentH.Purge)
						// Per-corpus Trash list + Empty Trash (Trash spec §5).
						r.Get("/{id}/trash", documentH.ListTrash)
						r.Post("/{id}/trash:empty", documentH.EmptyTrash)
					})
				})

				r.Route("/documents", func(r chi.Router) {
					r.Get("/{id}", documentH.Get)
					// NOTE: GET "/{id}/raw" (GetRawFile) is registered above,
					// outside this Timeout-wrapped group.
					r.Delete("/{id}", documentH.Delete)
					// Colon-suffix action routes for document.
					r.Post("/{id}:move", documentH.Move)
					r.Post("/{id}:rename", documentH.Rename)
					r.Post("/{id}:copy", documentH.Copy)
					r.Post("/{id}:preview-delete", documentH.PreviewDelete)
				})

				// Folder routes (not scoped to a corpus).
				//
				// Chi v5 requires every pattern to start with "/", so the
				// colon-suffix action routes are registered at the outer
				// scope alongside the document action routes rather than
				// nested under `r.Route("/folders/{folderId}", ...)`. The
				// nested form was tried first and panics at construction time
				// with "routing pattern must begin with '/'".
				r.Patch("/folders/{folderId}", folderH.Rename)
				r.Delete("/folders/{folderId}", folderH.Delete)
				r.Post("/folders/{folderId}:move", folderH.Move)
				r.Post("/folders/{folderId}:preview-delete", folderH.PreviewDelete)

				r.Route("/ingest-jobs", func(r chi.Router) {
					r.Get("/{id}", ingestH.GetJobStatus)
				})

				r.Route("/entities", func(r chi.Router) {
					r.Post("/", entityH.Create)
					r.Get("/{id}", entityH.Get)
					r.Patch("/{id}", entityH.Update)
					r.Delete("/{id}", entityH.Delete)
					r.Post("/search", entityH.Search)
					r.Get("/{id}/neighborhood", edgeH.Neighborhood)
					r.Get("/{id}/audit", entityH.Audit)
				})

				r.Route("/edges", func(r chi.Router) {
					r.Post("/", edgeH.Add)
					r.Get("/{id}", edgeH.Get)
					r.Patch("/{id}", edgeH.Update)
					r.Delete("/{id}", edgeH.Remove)
					r.Get("/{id}/audit", edgeH.Audit)
				})

				r.Get("/entity-types", typesH.ListEntityTypes)
				r.Get("/relationship-types", typesH.ListRelationshipTypes)
			})
		})
	})

	return r
}

func healthzHandler(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte("ok"))
}


