// TestNew_RouterConstructionDoesNotPanic guards against chi route-pattern
// panics at startup. chi v5 requires every pattern to begin with "/", so a
// bare colon-suffix like `r.Post(":move", ...)` inside `r.Route("/folders/{id}",
// ...)` panics at construction time with "routing pattern must begin
// with '/'". The handler unit tests instantiate handlers directly and never
// exercise the router, so the failure mode is invisible until the binary
// boots in Docker.
//
// Keeping this test in place ensures any future colon-suffix route slip-up
// is caught by `go test` rather than by a crash-looping production container.
func TestNew_RouterConstructionDoesNotPanic(t *testing.T) {
	deps := Deps{
		// Verifier is wired into a middleware factory at route
		// registration; the factory stores the pointer but never
		// dereferences it during construction. nil is safe for this
		// test — we never let a real request hit the auth middleware.
		Verifier: nil,
		// FilesClient is dereferenced for handler construction; an empty
		// struct is sufficient because routes only register handler
		// methods, never invoke them.
		FilesClient: &filesclient.Client{},
	}

	var handler http.Handler
	require.NotPanics(t, func() {
		handler = New(deps)
	})
	require.NotNil(t, handler)

	// Sanity: /healthz responds (proves the router is alive end-to-end).
	rec := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet, "/healthz", nil)
	handler.ServeHTTP(rec, req)
	require.Equal(t, http.StatusOK, rec.Code)
}

// TestNew_RouterIncludesTrashRoutes pins every new trash route so a future
// refactor can't silently remove them (or panic at startup like the chi-folder
// routes bug from PR #213).
//
// Note on test strategy: under the files-bff chi tree, the auth middleware
// group wraps ALL /api/v1/files/* paths, meaning both registered and
// unregistered sub-paths return 401 (not 404) when no bearer token is
// present. A simple "not 404" HTTP probe cannot distinguish a registered route
// from a missing one. We therefore use chi.Walk — which introspects the router
// trie directly without making HTTP requests — to assert the expected
// (method, pattern) pairs are present.
func TestNew_RouterIncludesTrashRoutes(t *testing.T) {
	deps := Deps{
		Verifier:    nil,
		FilesClient: &filesclient.Client{},
	}
	handler := New(deps)

	// New returns http.Handler; the concrete type is *chi.Mux which implements
	// chi.Router. Type-assert so we can use chi.Walk for route introspection.
	r, ok := handler.(chi.Router)
	require.True(t, ok, "server.New must return a chi.Router (got %T)", handler)

	// Build a set of "METHOD pattern" strings actually registered.
	registered := make(map[string]bool)
	err := chi.Walk(r, func(method, route string, _ http.Handler, _ ...func(http.Handler) http.Handler) error {
		registered[fmt.Sprintf("%s %s", method, route)] = true
		return nil
	})
	require.NoError(t, err, "chi.Walk failed")

	want := []struct{ method, pattern string }{
		{"POST", "/api/v1/files/corpora/{id}/documents/{docId}:trash"},
		{"POST", "/api/v1/files/corpora/{id}/documents/{docId}:restore"},
		{"POST", "/api/v1/files/corpora/{id}/documents/{docId}:purge"},
		{"POST", "/api/v1/files/corpora/{id}/documents/{docId}:preview-purge"},
		{"GET", "/api/v1/files/corpora/{id}/trash"},
		{"POST", "/api/v1/files/corpora/{id}/trash:empty"},
		// Phase C document-menu routes (raw download, rename, copy).
		{"GET", "/api/v1/files/documents/{id}/raw"},
		{"POST", "/api/v1/files/documents/{id}:rename"},
		{"POST", "/api/v1/files/documents/{id}:copy"},
	}
	for _, w := range want {
		key := fmt.Sprintf("%s %s", w.method, w.pattern)
		if !registered[key] {
			t.Errorf("route not registered: %s (all registered routes logged below)", key)
		}
	}
	if t.Failed() {
		t.Log("registered routes:")
		for k := range registered {
			t.Log(" ", k)
		}
	}
}

