// TestNew_ResolveOrgRole_ScopedToTrashOverrideRoutes pins that the ResolveOrgRole
// middleware (which resolves + forwards x-org-role for the admin override) is
// mounted on EXACTLY the three trash-override routes that files-svc gates on the
// org role — Purge, ListTrash, EmptyTrash — and on NO other files route. Adding
// the org-svc round-trip to corpora/documents/entity routes would be a
// per-request regression; dropping it from the override routes would silently
// disable the admin override.
//
// chi.Walk reports the per-route middleware chain. ResolveOrgRole is closed over
// the verifier, so we identify it structurally: it is the only route-scoped
// middleware that appears on the override routes and is absent everywhere else.
// We count the middleware-chain length per route — the override routes carry one
// extra route-scoped middleware (ResolveOrgRole) beyond the shared group
// middleware that every authenticated route carries.
func TestNew_ResolveOrgRole_ScopedToTrashOverrideRoutes(t *testing.T) {
	deps := Deps{
		Verifier:    nil,
		FilesClient: &filesclient.Client{},
		OrgClient:   &fakeOrgRoleVerifier{},
	}
	handler := New(deps)

	r, ok := handler.(chi.Router)
	require.True(t, ok, "server.New must return a chi.Router (got %T)", handler)

	// Map "METHOD pattern" → count of route-scoped middlewares chi attached.
	mwCount := make(map[string]int)
	err := chi.Walk(r, func(method, route string, _ http.Handler, mws ...func(http.Handler) http.Handler) error {
		mwCount[fmt.Sprintf("%s %s", method, route)] = len(mws)
		return nil
	})
	require.NoError(t, err, "chi.Walk failed")

	override := []string{
		"POST /api/v1/files/corpora/{id}/documents/{docId}:purge",
		"GET /api/v1/files/corpora/{id}/trash",
		"POST /api/v1/files/corpora/{id}/trash:empty",
	}
	// A baseline non-override corpora route — must NOT carry the extra middleware.
	const baseline = "GET /api/v1/files/corpora/{id}"

	baselineMW, baselineOK := mwCount[baseline]
	require.True(t, baselineOK, "baseline route %q not registered", baseline)

	for _, key := range override {
		got, found := mwCount[key]
		require.True(t, found, "override route %q not registered", key)
		require.Equal(t, baselineMW+1, got,
			"override route %q should carry exactly one extra route-scoped middleware (ResolveOrgRole) over the baseline %q", key, baseline)
	}

	// Sentinel: a sampling of non-override routes must match the baseline
	// middleware count — i.e. they do NOT carry ResolveOrgRole.
	for _, key := range []string{
		"POST /api/v1/files/corpora/{id}/documents/{docId}:trash",
		"POST /api/v1/files/corpora/{id}/documents/{docId}:restore",
		"POST /api/v1/files/corpora/{id}/documents/{docId}:preview-purge",
		"POST /api/v1/files/entities/search",
		"POST /api/v1/files/edges/",
	} {
		got, found := mwCount[key]
		require.True(t, found, "route %q not registered", key)
		require.Equal(t, baselineMW, got,
			"non-override route %q must NOT carry ResolveOrgRole (same middleware count as baseline)", key)
	}
}

// mountClientIPProbe adds a diagnostic route that echoes security.ClientIP(r)
// as the response body. New()'s underlying *chi.Mux only builds its handler
// once (on the first route add inside New itself); inserting one more route
// into the still-live radix tree afterward is safe and lets tests observe
// what the ClientIP middleware resolved without needing a production route
// that exposes it.
func mountClientIPProbe(t *testing.T, h http.Handler) {
	t.Helper()
	mux, ok := h.(chi.Router)
	require.True(t, ok, "New() did not return a chi.Router (got %T)", h)
	mux.Get("/__test_clientip", func(w http.ResponseWriter, r *http.Request) {
		_, _ = w.Write([]byte(security.ClientIP(r)))
	})
}

// TestClientIPMiddleware_UntrustedRemoteAddr_IgnoresForgedXFF proves that a
// direct caller (RemoteAddr outside TrustedProxyCIDRs) cannot spoof its
// resolved client IP via X-Forwarded-For — closing the gap RealIP left open.
func TestClientIPMiddleware_UntrustedRemoteAddr_IgnoresForgedXFF(t *testing.T) {
	trusted := []netip.Prefix{netip.MustParsePrefix("10.0.0.0/8")}
	deps := Deps{FilesClient: &filesclient.Client{}, TrustedProxyCIDRs: trusted}
	h := New(deps)
	mountClientIPProbe(t, h)

	req := httptest.NewRequest(http.MethodGet, "/__test_clientip", nil)
	req.RemoteAddr = "203.0.113.9:12345" // NOT in the trusted set
	req.Header.Set("X-Forwarded-For", "198.51.100.1")
	req.Header.Set("True-Client-IP", "198.51.100.1")
	rr := httptest.NewRecorder()
	h.ServeHTTP(rr, req)

	require.Equal(t, "203.0.113.9", rr.Body.String(),
		"forged XFF from an untrusted peer must be ignored")
}

// TestClientIPMiddleware_TrustedRemoteAddr_HonorsXFF proves that a request
// proxied through a peer inside TrustedProxyCIDRs resolves to the real
// client IP carried in X-Forwarded-For.
func TestClientIPMiddleware_TrustedRemoteAddr_HonorsXFF(t *testing.T) {
	trusted := []netip.Prefix{netip.MustParsePrefix("10.0.0.0/8")}
	deps := Deps{FilesClient: &filesclient.Client{}, TrustedProxyCIDRs: trusted}
	h := New(deps)
	mountClientIPProbe(t, h)

	req := httptest.NewRequest(http.MethodGet, "/__test_clientip", nil)
	req.RemoteAddr = "10.0.0.5:12345" // inside the trusted set
	req.Header.Set("X-Forwarded-For", "198.51.100.1")
	rr := httptest.NewRecorder()
	h.ServeHTTP(rr, req)

	require.Equal(t, "198.51.100.1", rr.Body.String(),
		"legitimately proxied request should resolve to the real client")
}



