// TestNew_NoStreamingRouteBoundByTimeout guards the hazard documented on
// httpserver.Timeout: it cancels the request's context.Context when it
// fires, which correctly-behaving SSE/streaming handlers select on and
// exit — so a streaming or upload route mounted inside a Timeout group is
// silently truncated in production.
//
// GET .../documents/{id}/raw (streams the file body) and
// POST .../corpora/{id}/documents (streams the multipart upload) are
// registered OUTSIDE the httpserver.Timeout group in New() specifically to
// avoid this. routeaudit detects both by inspecting each route's actual
// handler source (http.Flusher/Flush()/io.Copy/multipart signals) rather
// than by name, so this test also catches a FUTURE streaming route
// mistakenly added inside the Timeout group, without needing to know its
// path in advance.
func TestNew_NoStreamingRouteBoundByTimeout(t *testing.T) {
	deps := Deps{
		Verifier:    nil,
		FilesClient: &filesclient.Client{},
	}
	handler := New(deps)

	r, ok := handler.(chi.Router)
	require.True(t, ok, "server.New must return a chi.Router (got %T)", handler)

	routeaudit.AssertNoStreamingRouteBoundByTimeout(t, r)
}


