func TestHealthz(t *testing.T) {
	h := http.HandlerFunc(healthzHandler)
	req := httptest.NewRequest(http.MethodGet, "/healthz", nil)
	rr := httptest.NewRecorder()

	h.ServeHTTP(rr, req)

	if rr.Code != http.StatusOK {
		t.Errorf("status = %d, want 200", rr.Code)
	}
	if got := rr.Body.String(); got != "ok" {
		t.Errorf("body = %q, want %q", got, "ok")
	}
	if got := rr.Header().Get("Content-Type"); got != "text/plain; charset=utf-8" {
		t.Errorf("content-type = %q", got)
	}
}

// TestNew_SetsSecurityHeaders pins CR-M2: every files-bff response must carry
// the day-1 security headers set by platform/libs/go/security.Middleware.
//
// shell-bff already applies security.Middleware; files-bff does NOT yet, so its
// API responses ship without these headers. This test goes through the full
// router via New and hits the always-registered /healthz route (no JWT
// required), asserting the four headers are present with their canonical values
// (mirrored from platform/libs/go/security/headers_test.go).
//
// RED today: New does not apply security.Middleware, so the headers are absent
// (empty) and every assertion fails on a missing header — NOT a router
// construction error.
func TestNew_SetsSecurityHeaders(t *testing.T) {
	deps := Deps{
		Verifier:    nil,
		FilesClient: &filesclient.Client{},
	}
	handler := New(deps)

	rec := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet, "/healthz", nil)
	handler.ServeHTTP(rec, req)

	require.Equal(t, "nosniff", rec.Header().Get("X-Content-Type-Options"),
		"X-Content-Type-Options missing — security.Middleware not applied")
	require.Equal(t, "DENY", rec.Header().Get("X-Frame-Options"),
		"X-Frame-Options missing — security.Middleware not applied")
	require.Equal(t, "max-age=31536000; includeSubDomains", rec.Header().Get("Strict-Transport-Security"),
		"Strict-Transport-Security missing — security.Middleware not applied")
	require.Equal(t, "strict-origin-when-cross-origin", rec.Header().Get("Referrer-Policy"),
		"Referrer-Policy missing — security.Middleware not applied")
}

// TestNew_RouterConstructionDoesNotPanic guards against chi route-pattern
// panics at startup. chi v5 requires every pattern to begin with "/", so a
// bare colon-suffix like `r.Post(":move", ...)` inside `r.Route("/folders/{id}",
// ...)` panics at construction time with "routing pattern must begin
// with '/'". The handler unit tests instantiate handlers directly and never
// exercise the router, so the failure mode is invisible until the binary
// boots in Docker.
//
// Keeping this test in place ensures any future colon-suffix route slip-up
// is caught by `go test` rather than by a crash-looping production container.
func TestNew_RouterConstructionDoesNotPanic(t *testing.T) {
	deps := Deps{
		// Verifier is wired into a middleware factory at route
		// registration; the factory stores the pointer but never
		// dereferences it during construction. nil is safe for this
		// test — we never let a real request hit the auth middleware.
		Verifier: nil,
		// FilesClient is dereferenced for handler construction; an empty
		// struct is sufficient because routes only register handler
		// methods, never invoke them.
		FilesClient: &filesclient.Client{},
	}

	var handler http.Handler
	require.NotPanics(t, func() {
		handler = New(deps)
	})
	require.NotNil(t, handler)

	// Sanity: /healthz responds (proves the router is alive end-to-end).
	rec := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet, "/healthz", nil)
	handler.ServeHTTP(rec, req)
	require.Equal(t, http.StatusOK, rec.Code)
}

// TestNew_RouterIncludesTrashRoutes pins every new trash route so a future
// refactor can't silently remove them (or panic at startup like the chi-folder
// routes bug from PR #213).
//
// Note on test strategy: under the files-bff chi tree, the auth middleware
// group wraps ALL /api/v1/files/* paths, meaning both registered and
// unregistered sub-paths return 401 (not 404) when no bearer token is
// present. A simple "not 404" HTTP probe cannot distinguish a registered route
// from a missing one. We therefore use chi.Walk — which introspects the router
// trie directly without making HTTP requests — to assert the expected
// (method, pattern) pairs are present.
func TestNew_RouterIncludesTrashRoutes(t *testing.T) {
	deps := Deps{
		Verifier:    nil,
		FilesClient: &filesclient.Client{},
	}
	handler := New(deps)

	// New returns http.Handler; the concrete type is *chi.Mux which implements
	// chi.Router. Type-assert so we can use chi.Walk for route introspection.
	r, ok := handler.(chi.Router)
	require.True(t, ok, "server.New must return a chi.Router (got %T)", handler)

	// Build a set of "METHOD pattern" strings actually registered.
	registered := make(map[string]bool)
	err := chi.Walk(r, func(method, route string, _ http.Handler, _ ...func(http.Handler) http.Handler) error {
		registered[fmt.Sprintf("%s %s", method, route)] = true
		return nil
	})
	require.NoError(t, err, "chi.Walk failed")

	want := []struct{ method, pattern string }{
		{"POST", "/api/v1/files/corpora/{id}/documents/{docId}:trash"},
		{"POST", "/api/v1/files/corpora/{id}/documents/{docId}:restore"},
		{"POST", "/api/v1/files/corpora/{id}/documents/{docId}:purge"},
		{"POST", "/api/v1/files/corpora/{id}/documents/{docId}:preview-purge"},
		{"GET", "/api/v1/files/corpora/{id}/trash"},
		{"POST", "/api/v1/files/corpora/{id}/trash:empty"},
		// Phase C document-menu routes (raw download, rename, copy).
		{"GET", "/api/v1/files/documents/{id}/raw"},
		{"POST", "/api/v1/files/documents/{id}:rename"},
		{"POST", "/api/v1/files/documents/{id}:copy"},
	}
	for _, w := range want {
		key := fmt.Sprintf("%s %s", w.method, w.pattern)
		if !registered[key] {
			t.Errorf("route not registered: %s (all registered routes logged below)", key)
		}
	}
	if t.Failed() {
		t.Log("registered routes:")
		for k := range registered {
			t.Log(" ", k)
		}
	}
}

// ---------- Feature flag gate ----------

// filesFlagDisabledBody is the JSON shape emitted by RequireVerticalEnabled.
type filesFlagDisabledBody struct {
	Error struct {
		Code string `json:"code"`
	} `json:"error"`
}

// makeFilesFlagCache returns a featureflags.Cache whose fetcher always returns
// the provided enabled value for the "files" vertical.
func makeFilesFlagCache(enabled bool) *featureflags.Cache {
	return featureflags.NewCache(func(_ context.Context) (map[string]bool, error) {
		return map[string]bool{"files": enabled}, nil
	}, 10*time.Second, slog.Default())
}

// TestFilesVerticalGate_MiddlewareDisabled_Returns403 tests the
// RequireVerticalEnabled("files") middleware directly — bypassing the full
// server stack (which would return 401 from JWT auth before reaching the gate)
// — to verify it returns 403 with vertical_disabled when the cache reports the
// files vertical disabled.
func TestFilesVerticalGate_MiddlewareDisabled_Returns403(t *testing.T) {
	cache := makeFilesFlagCache(false)
	mw := featureflags.RequireVerticalEnabled(cache, "files")

	var nextCalled bool
	next := http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		nextCalled = true
		w.WriteHeader(http.StatusOK)
	})

	req := httptest.NewRequest(http.MethodGet, "/api/v1/files/corpora", nil)
	rr := httptest.NewRecorder()
	mw(next).ServeHTTP(rr, req)

	require.Equal(t, http.StatusForbidden, rr.Code,
		"expected 403 when files vertical disabled")
	require.False(t, nextCalled, "next handler must NOT be called when vertical disabled")

	var body filesFlagDisabledBody
	require.NoError(t, json.NewDecoder(rr.Body).Decode(&body))
	require.Equal(t, "vertical_disabled", body.Error.Code)
}

// TestFilesVerticalGate_NilCache_PassesThrough asserts that a nil
// FeatureFlagCache (ORG_SVC_ADDR unset in local dev) leaves the files routes
// ungated: a request reaches the JWT auth layer (401 without a bearer) rather
// than being short-circuited with 403.
func TestFilesVerticalGate_NilCache_PassesThrough(t *testing.T) {
	h := New(Deps{
		Verifier:    nil,
		FilesClient: &filesclient.Client{},
		// FeatureFlagCache left nil.
	})

	req := httptest.NewRequest(http.MethodGet, "/api/v1/files/corpora", nil)
	rr := httptest.NewRecorder()
	h.ServeHTTP(rr, req)

	require.NotEqual(t, http.StatusForbidden, rr.Code,
		"got 403 with nil cache — nil must be a pass-through no-op")
}

// TestFilesVerticalGate_MiddlewareEnabled_PassesThrough asserts that when the
// files vertical is enabled the middleware calls next (no 403).
func TestFilesVerticalGate_MiddlewareEnabled_PassesThrough(t *testing.T) {
	cache := makeFilesFlagCache(true)
	mw := featureflags.RequireVerticalEnabled(cache, "files")

	var nextCalled bool
	next := http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		nextCalled = true
		w.WriteHeader(http.StatusOK)
	})

	req := httptest.NewRequest(http.MethodGet, "/api/v1/files/corpora", nil)
	rr := httptest.NewRecorder()
	mw(next).ServeHTTP(rr, req)

	require.NotEqual(t, http.StatusForbidden, rr.Code,
		"got 403 vertical_disabled even though files vertical is enabled")
	require.True(t, nextCalled, "next handler must be called when vertical enabled")
}

